-- Megaverse in Flames: Soulmancy spells, levels thirteen to fifteen and the Spells of Legend.
-- 13 spells rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~343-megaverse-in-flames-spells-d.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
-- Soulmancy, levels thirteen to fifteen and the three Spells of Legend, by the
-- spell list on printed p.91; every level agrees with the description headings
-- (p.105-111) and the Contents (p.5). Every cost and stat line was read off a
-- render. Names keep the description heading as printed. The Spells of Legend
-- take level 15 and a ppe_note opening "A Spell of Legend, beyond the fifteen
-- levels", as the held legends do. One cost differs: the list gives Summon
-- Demon Planet as 5,000 +35,600 and its description adds 2,000 for the contact
-- ritual; the description wins and the list's reading is its variant_note.
-- The Flesh Golem's stats stay in its spell row; no creatures row.

INSERT OR IGNORE INTO spells (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition, ppe_permanent) VALUES
  ('Soulmancy: Blood Pool (Ritual)', 13, 400, '400 P.P.E. plus one soul', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.105', 'rifts', 'Touch', 'Two weeks per level of the caster; each further sacrifice drained into the pool, numbering the creator''s level, adds two weeks, and past that the creation ritual must be repeated before the last day', NULL, 'Not applicable', NULL, 'Ritual of two hours; at least eight victims are killed for their blood and one captured soul completes it', 'Fills a carved basin about the size of a small swimming pool with sacrificial blood and binds it with a soul, giving the Soulmancer a working pool that is a fixture of every Soulmancer''s and Hell Lord''s lair. Its carvings mark the patron Demon Lord and hold the power in place; most pools can take at least one large demon. A pool may serve one purpose or several: bathing in it heals 1D6 S.D.C./Hit Points or 1D4 M.D.C. a minute, though frequent users grow blood-red scars; it refills blood tanks and ammunition for Blood Weapons and keeps the blood from drying; touching the right glyphs and naming someone at another pool opens two-way talk, and reaching another dimension costs 25 P.P.E. by sacrifice or channelling; bodies and parts laid in it stay perfectly preserved; it can store two souls per level of its maker, their faces showing in the blood; and some Soulmancy creation magic names it as its liquid medium.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Blood Rift', 13, 350, '350 P.P.E. plus the blood of four sacrificed people, whose P.P.E. and life essences the ritual consumes', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.106', 'rifts', 'Limited to one dimension', 'The portal stays open one hour per level of the spell caster and reopens if someone cuts himself for 1D6 S.D.C.; the blood pool dries up after one day per level of the caster', NULL, 'Not applicable; a Close Rift spell dries up the pit and ends the spell', NULL, 'Ritual: a shallow pit is dug and carved with grooves and glyphs, then four sentient beings are sacrificed to fill it', 'Turns a pit only a few inches deep into a gateway to one other dimension, bought with the blood of innocents. Demons or people climb down into the blood and spend 1D4 melee rounds wading through what feels like a mire before coming out the far side drenched from head to toe. The rift goes only to the destination inscribed in the pit, and a matching pit appears at the far end so the way works in both directions. As with most dimensional magic, the maker must have been to that dimension before.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Flesh Golem (Ritual)', 13, 400, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.106-107', 'rifts', 'Touch', 'One month per level of the spell caster; with a Permanency spell it lasts until destroyed', NULL, 'None', NULL, 'Ritual', 'Like Create Golem, but the servant is built from a corpse or enough parts to make one, with a Soul Crystal sealed somewhere inside. It rises 24 hours after the ritual and, however badly it is destroyed, rises again 24 hours later; only smashing the hidden crystal ends it. The flesh keeps rotting unless Permanency is added, so some Soulmancers keep golems in Blood Pools until needed, and many build a quick temporary army of them. A golem can be improved with Soul Body (raising Soul Mind risks a golem that thinks for itself and slips its master''s control), extra limbs, wings with Fly as the Eagle, Superhuman Speed and the like, all cast during the creation and bound by Permanency. The unaltered golem: effectively Anarchist, Horror Factor 14, I.Q. 7, M.E. 6, M.A. 4, P.S. 20 (Supernatural), P.P. 10, P.E. 18 (Supernatural), P.B. 1D6, Spd 10, size varies, 3D6x10 M.D.C. It is impervious to many psychic and magic attacks, to bio-manipulation and mental attacks, to possession and Horror Factor, and to normal fire and cold (half damage from magic and M.D. fire and cold); it needs no air or food, so gas, disease and any ocean depth do not trouble it. Each extra pair of arms or tentacles adds one attack, a centaur''s lower body raises Spd to 80, and sewn-on M.D. hide adds 50 M.D.C. at a time to a 500 maximum; it can wear M.D. body armor if its shape allows. Four attacks per melee, by Supernatural P.S. (1D6 M.D. punch, 2D6 M.D. kick) or a weapon, with no parry, dodge or initiative bonuses unless spells add them.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Death by 1,000 Cuts (Ritual)', 14, 500, '500 P.P.E. plus ritual self-mutilation', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.107', 'rifts', '1,000 miles (1,600 km) per level of experience; two light years per level of the spell caster on a Demon Planet', 'The ritual takes six hours; the damage lands all at once at its end', 'One Hit Point to a mortal S.D.C. being, or one M.D. to a Mega-Damage, supernatural or magical being, for every cut the caster gives himself: at least 500 cuts (the minimum for the ritual to work) and at most 1,000; 30% less when only a photograph ties the effigy to the victim. A successful save still costs half the victim''s Hit Points or M.D.C.', 'Save vs ritual magic: 16 or higher by the stat line, 17 or higher by the text. A success means a moment of crippling pain and the loss of half the victim''s Hit Points (or M.D.C.), leaving no wounds and healing normally', NULL, 'Ritual of six hours: three binding and bleeding a demon or Deevil, three of the caster cutting himself', 'A ritual of agony for the caster. For the first three hours a captive demon or Deevil is bled, not killed, and its blood draws a circled pentagram and spells out the victim''s name around an effigy of rags or straw carrying the victim''s hair, skin, nails or blood, a personal belonging, or failing those a photograph pinned on by a knife through the throat or heart. For the last three hours the caster slashes or lashes himself over the effigy, the circle keeping him alive through every cut, then stabs the effigy for the killing blow and every cut strikes the victim at once, wherever he is. Nothing defends against it but sheltering in a Circle of Protection: Superior or a like sanctuary, and the stored attack strikes the instant the victim leaves it. If the damage exceeds half his usual Hit Points (or M.D.C.) he falls into a coma: save vs coma and death at +15% with no Bio-Regeneration, and failure means death even so. A survivor''s wounds do not start to heal for 1D4 days, even with Bio-Regeneration. When the attack lands, the caster''s own cuts vanish and he learns whether the target lived. If the victim saves, the caster drops to 1D6 Hit Points and S.D.C. (M.D.C. for a Mega-Damage caster), is scarred for life whatever healing he gets (P.B. and M.E. -4, S.D.C. -20%) and rolls on the core book''s Random Insanity Table; while a delayed attack waits for its victim, the caster suffers the same until it lands.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Soul Resurrection', 14, 175, '175 P.P.E. plus one soul', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.107', 'rifts', 'Touch or within 10 feet (3 m); line of sight required', 'The ritual takes 1D4 hours; the restored life is permanent', NULL, 'None', NULL, 'Ritual of 1D4 hours', 'Trades one life for another: the Soulmancer uses a captured life essence to bring back someone who died no more than 48 hours before. The soul can be taken from a Soul Crystal, a Blood Pool, or someone slain during the casting, and it is used up forever. Success is not certain: 66% plus 2% per level of the caster.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Create Blood Pillar (Ritual)', 15, 1000, '1,000 P.P.E. plus two souls', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.108', 'rifts', 'Touch', 'Permanent, until destroyed', NULL, 'None', NULL, 'Ritual', 'Raises a stone pillar, 10 to 20 feet (3 to 6 m) tall and weighing 20 to 80 tons, carved top to bottom with glyphs and often with pictures of its patron Demon or Deevil Lord, his legions and the sacrifices that consecrated the site; every pillar in one structure, such as a Hell Pit, is of the same stone. A pillar is a P.P.E. battery holding up to 1,000 points. It recharges 10 an hour on a ley line or 20 on a nexus; elsewhere it is filled by blood sacrifice, by a ritual in which each participant lends half his P.P.E. (recovered normally), or by pumping in one''s own. To draw on it, the participants cut themselves for at least 1D6 S.D.C. and smear blood on the stone while chanting their leader''s name, and that leader must bleed on it too; he alone may then spend the stored P.P.E. and, if needed, half of each participant''s. Without his blood nothing can be drawn. Every user''s blood is soaked into the stone and makes him forever known to the pillar''s Dark One, who counts him a follower and may call in a favor. Each pillar has 1,000 M.D.C. and heals 100 M.D.C. every 24 hours (12 on a ley line nexus); reduced to zero it crumbles to dust that turns to blood and stains the ground for 1D4 years.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Curse: Eternal Torment', 15, 100, '800 as a ritual or 100 as a spell', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.108-109', 'rifts', 'Touch; a living person, or a life essence held in a medium such as a Soul Crystal', 'Permanent as a ritual; 10 hours per level of the Soulmancer as a spell', NULL, 'Standard: 16 against the ritual, 13 against the spell. A success against the spell (or a Blood Warrior''s attack) means no effect; against the ritual it inflicts one torment for only 1D4 minutes', NULL, 'Spell or ritual; only the ritual is permanent, so its victim must be held for it', 'Convinces a person or spirit, Astral Beings and Entities included, that he suffers a dreadful affliction; the G.M. rolls percentile or picks. 01-17 Tortured Dreams: a vivid nightmare of loved ones or himself suffering returns within 1D6x10 minutes of every sleep, leaving him exhausted (-3 Perception and initiative, -15% skills, -1D4 P.E., Spd -10%, tires twice as fast). 18-34 Terrible Disfigurement: he sees a monster in every mirror and believes his P.B. is 1D6, hides himself, neglects his looks and may become a recluse (M.A. halved, M.E. -1D4). 35-50 Dead Limb: a numb dead arm (-2 attacks, -2 all combat rolls, -20% on hand and balance skills, -1 M.A., -1D4 P.P. and P.B.) or dead leg (-1 attack, no dodge bonus or automatic dodge, -1 combat rolls, -40% on leg and balance skills, -1 M.A., -1D4 P.P., Spd halved); a prosthetic or bionic replacement only halves the penalties, rounding up. 51-66 Crippling Illness: constant pain from an undiagnosable disease (-1 attack, -1D6 Perception and initiative, -10% skills, -1 M.A., -1D4 P.E., Spd -20%) plus a phobia and obsession rolled on percentile: germs with hypochondria, germs with compulsive cleaning, blood and slime, or Soulmancers. 67-83 Tormented by Mental Illness: one roll each on the Neurosis, Random Phobia and Random Obsession tables of Rifts Ultimate Edition (p.333 on). 84-00 Doombringer: he sees omens of doom daily, half of them true, has bad luck and blames himself for every disaster around him (-1 attack, -1D4 Perception, -1 parry and dodge, -2 save vs magic and illusion, -5% skills or -30% drunk or drugged, -1 M.A. and M.E.). The tormented never find lasting relief.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Permanency (Ritual)', 15, 100, '100, plus the P.P.E. of each spell made permanent, and a soul for every 25 P.P.E. of the total (five at the least)', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.109', 'rifts', 'Touch or 5 feet (1.5 m); line of sight required', 'Permanent', NULL, 'Standard for ritual magic, where one applies', NULL, 'Ritual', 'The Soulmancers'' answer to the old quest for lasting magic: life essences are the key that fixes another spell in place for good, always on, on a living subject or built into an item. Any spell that lasts for a time qualifies; an instant one usually does not. The price is steep and the ritual needs careful preparation. A successful Negate Magic shuts the permanent spells off for 1D4 melee rounds, and stronger magic such as Anti-Magic Cloud suppresses them for its own duration if they fail to save, using the caster''s saving throws for an item or the subject''s own for a person.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Transfer Soul (Ritual)', 15, 750, '750, plus 100 for each additional 24 hours of duration', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.109-110', 'rifts', 'Touch or within one yard (one meter)', '48 hours plus 24 hours for each additional 100 P.P.E. spent; a Permanency ritual, with both people present, makes it permanent, which is rare', NULL, 'Standard for ritual, 16 or higher', NULL, 'Ritual, long and complicated', 'Swaps the life essences of two mortals, or of a mortal and a lesser supernatural being, and each mind, with all its personality, skills and experience, wakes in the other''s body. Soulmancers use it to escape bodies wrecked by bloodletting, which their youth magic cannot mend, or to plant a henchman or a master''s minion in an enemy''s or stranger''s body as a spy; demons find a mortal frame feeble, and mortals find a demon''s body alien and frightening. A supernatural spirit in a mortal body reads as an ordinary mortal, so the hard part is acting the part: acquaintances may see a change of character and suspect drugs or a breakdown sooner than a swap. Quick murder, kidnapping or theft suits it best, since the innocent owner returns to the body when the duration ends and takes the blame. Few know that the death of either body also ends it: the dead body''s soul passes on and the other goes home. A permanent swap has no reversal.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Soul Weapon (Ritual)', 15, 500, '500 P.P.E. plus one soul, usually a living donor slain at the ritual''s end', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.110', 'rifts', 'Touch or within one yard (one meter); line of sight required', 'Ten years per level of experience; triple on a nexus. The weapon then turns ordinary', '4D6 M.D., or the weapon''s own damage +1D6 if that is higher; an attempt to make it permanent blows it apart for 6D6 M.D. to everyone within 10 feet (3 m)', 'None', NULL, 'Ritual at an altar holding the weapon, which must then slay a living, sentient being', 'Perhaps the forerunner of Rune magic: an ordinary, unenchanted weapon laid on an altar absorbs the life essence of the sentient being it kills when the ritual ends. The result is light and well balanced, bonds to the first mortal or supernatural being who puts a drop of blood on it, and takes that person''s alignment, though it has no mind or voice of its own. Up to four other invocations, none above level 7 and none of Soulmancy or Necromancy, can be built in, each usable three times per 24 hours. It is no Rune weapon: 600 M.D.C. of damage shatters it, its power fades after decades, it reeks of supernatural evil to anyone sensitive to that, and Permanency only makes it explode.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Create Hell Pit (Ritual)', 15, 8000, 'A Spell of Legend, beyond the fifteen levels. 8,000 P.P.E., plus enough sacrifices to stain the ground around the Hell Pit''s altar and four Blood Pillars built around it; the souls of the sacrificed are consumed', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.110', 'rifts', 'Limited to one dimension', 'Permanent, until destroyed', NULL, 'Not applicable', NULL, 'Ritual', 'A Spell of Legend. Creates and activates a Hell Pit, a fragment of a hell dimension planted on another world (described at length early in the book, from printed p.23). Among its powers it opens Rifts, small ones for 100 P.P.E. and others wide enough for thousands of demon troops with their mounts and war machines, usually for an invasion. Its two-way portal joins a Hell Pit deep in Hell with any world, dimension or place where another active Hell Pit stands.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Summon Demon Planet', 15, 2000, 'A Spell of Legend, beyond the fifteen levels. 2,000 for the first contact ritual (often several attempts), 5,000 to keep the Communication Rift open for a year once contact is made, and 35,600 to complete the summoning', 'The spell list on printed p.91 gives the cost as 5,000 +35,600; the description''s P.P.E. line adds the 2,000 of the contact ritual, and the description wins a cost.', 'import', 'Rifts World Book 35: Megaverse in Flames p.111', 'rifts', 'Not applicable', 'Permanent, until destroyed', NULL, 'Not applicable', NULL, 'A series of rituals, each ending in the sacrifice of a dozen living beings, then the final summoning at a time and place the Demon Planet names', 'A Spell of Legend found only in the coded text of an ancient tome, Cormal, The Destroyer of Worlds, which reads as a plain book of legend without the key and may date to the first Dominator Dynasty; scholars guess, without proof, that a Demon Planet was once called against the Dominators. Each contact ritual has a 01-10% chance, rising 10% with every attempt, of opening a Communication Rift to the Floating Horror, the avatar of a Demon Planet. Once contact is held, the avatar names a moment, usually a planetary solstice or alignment, and a remote spot of space near a solar system it can feed on. The summoned world may ally with its summoners if given free rein and never treated as a servant, or it may devour them on a whim. Only sentient sacrifices can supply the P.P.E., which usually means thousands of lives.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Youthful Soul (Ritual)', 15, 800, 'A Spell of Legend, beyond the fifteen levels. 800 P.P.E. plus four souls torn away before their owners reached the age of 30', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.111', 'rifts', 'Self or by touch', 'Permanent; the recipient then ages normally from the new age', NULL, 'None', NULL, 'Ritual of six hours', 'A Spell of Legend that stands in for a fountain of youth: four consumed life essences make the caster or another recipient 5D4 years younger in body, erasing or easing the penalties of old age and stretching the life span. Aging resumes afterward, so the ritual may be repeated every few years for as long as P.P.E. and souls last. The scars of Soulmancers and Blood Warriors stay, so their P.B. and M.A. do not improve.', NULL, 'soulmancy', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 13 spells rows are in' AS assertion, count(*) AS got, 13 AS want
  FROM spells WHERE name IN ('Soulmancy: Blood Pool (Ritual)', 'Soulmancy: Blood Rift', 'Soulmancy: Flesh Golem (Ritual)', 'Soulmancy: Death by 1,000 Cuts (Ritual)', 'Soulmancy: Soul Resurrection', 'Soulmancy: Create Blood Pillar (Ritual)', 'Soulmancy: Curse: Eternal Torment', 'Soulmancy: Permanency (Ritual)', 'Soulmancy: Transfer Soul (Ritual)', 'Soulmancy: Soul Weapon (Ritual)', 'Soulmancy: Create Hell Pit (Ritual)', 'Soulmancy: Summon Demon Planet', 'Soulmancy: Youthful Soul (Ritual)') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~343-megaverse-in-flames-spells-d.sql');
